/* PrixRepère V1.4 — données personnelles conservées dans ce navigateur. */
'use strict';
const KEY='prixrepere_personnel_v1';
const LEGACY_STORES=[['u','Super U Prissé'],['leclerc','E.Leclerc Mâcon'],['carrefour','Carrefour Crêches-sur-Saône'],['auchan','Auchan Mâcon'],['imacon','Intermarché Mâcon'],['iperonne','Intermarché Péronne']];
let STORES=LEGACY_STORES;
const HOME_STORES=LEGACY_STORES.map(([id,name])=>({id,name,selected:true,osmId:null,osmType:null,lat:null,lon:null,url:id==='u'?'https://www.coursesu.com/drive-superu-prisse':''}));
function defaultZones(){return {home:{id:'home',label:'Maison',place:'Mâcon (71000)',lat:46.3069,lon:4.8313,radius:25,stores:HOME_STORES,lastScan:''},holiday:{id:'holiday',label:'Vacances',place:'',lat:null,lon:null,radius:15,stores:[],lastScan:''}}}

const BASECATS=[['poulet','Filets de poulet frais','kg'],['steak','Steaks hachés','kg'],['jambon','Jambon','kg'],['lait','Lait demi-écrémé','L'],['beurre','Beurre','kg'],['oeufs','Œufs','u'],['pates','Pâtes','kg'],['riz','Riz','kg'],['cafe','Café','kg'],['lessive','Lessive','L'],['papier','Papier toilette','u'],['sanytol','Désinfectant du linge Sanytol','L']].map(([id,name,unit])=>({id,name,unit}));
const today=()=>{let d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const N=n=>Number(String(n??'').replace(',','.').replace(/\s/g,''));
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro=v=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR'}).format(v);
const num=(v,n=2)=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:n,minimumFractionDigits:0}).format(v);
const uid=()=>Math.random().toString(36).slice(2)+Date.now().toString(36);
const dayAge=d=>Math.floor((new Date(today()+'T12:00:00')-new Date(d+'T12:00:00'))/86400000);
const rawSeed={id:'seed-superu-poulet',category:'poulet',store:'u',name:'Filet de poulet blanc PRIX MINI – France',code:'',packQty:1,packPrice:10.29,date:'2026-10-13',source:'Capture Courses U fournie par l’utilisateur',comment:'Barquette 1 kg; prix affiché sur la capture. Magasin Prissé selon lien du Drive.'};
function initial(){return {categories:BASECATS,prices:[rawSeed],list:[{id:'l1',category:'poulet',qty:1,exact:''},{id:'l2',category:'lait',qty:6,exact:''},{id:'l3',category:'pates',qty:2,exact:''},{id:'l4',category:'beurre',qty:.5,exact:''},{id:'l5',category:'oeufs',qty:12,exact:''}],alerts:[{id:'a1',category:'poulet',kind:'target',value:7.9,exact:'',lastKey:''}],settings:{maxAge:14},notices:[],onlineOffers:[],zones:defaultZones(),activeZone:'home'}}
function load(){try{let x=JSON.parse(localStorage.getItem(KEY));if(!x||!Array.isArray(x.prices)||!Array.isArray(x.categories)||!Array.isArray(x.list)||!Array.isArray(x.alerts))throw Error('Invalid');return {...initial(),...x,categories:[...x.categories,...BASECATS.filter(c=>!x.categories.some(xc=>xc.id===c.id))],settings:{...initial().settings,...x.settings},onlineOffers:Array.isArray(x.onlineOffers)?x.onlineOffers:[],zones:normalizeZones(x.zones),activeZone:['home','holiday'].includes(x.activeZone)?x.activeZone:'home'}}catch{return initial()}}
function normalizeZones(z){const d=defaultZones();for(const k of ['home','holiday'])if(z&&z[k]){d[k]={...d[k],...z[k]};d[k].stores=Array.isArray(d[k].stores)?d[k].stores:[];d[k].stores=d[k].stores.filter(x=>x&&x.id&&x.name).map(x=>({...x,selected:!!x.selected}))}if(!d.home.stores.length)d.home.stores=HOME_STORES;return d}
let state=load(),tab='accueil',scannedImage=null,ocrBusy=false,externalPrices=[],onlineImage=null;
let scanResult=null,scanImageUrl='',scanPromoNeedsConfirm=false;
function activeZone(){return state.zones[state.activeZone]}
function storeInArea(s,z=activeZone()){return !(Number.isFinite(s.lat)&&Number.isFinite(s.lon)&&Number.isFinite(z.lat)&&Number.isFinite(z.lon))||distKm(z.lat,z.lon,s.lat,s.lon)<=z.radius;}
function refreshStores(){STORES=activeZone().stores.filter(s=>s.selected&&storeInArea(s)).map(s=>[s.id,s.name]);}
refreshStores();
let discoveredShops=[],areaPrices=[],areaPriceMeta='';
function storeById(id){return Object.values(state.zones).flatMap(z=>z.stores).find(s=>s.id===id)}
function osmKey(type,id){return type&&id?`osm:${String(type).toLowerCase()}:${id}`:null}
function areaText(){const z=activeZone();return `${z.label} : ${z.place||'zone à définir'} · ${z.radius} km · ${STORES.length} magasin(s)`}
function enterZone(k){if(!state.zones[k])return;state.activeZone=k;refreshStores();persist();discoveredShops=[];areaPrices=[];areaPriceMeta='';render();checkAlerts()}

let remoteOffers=[],remoteQuery='',remoteFetchTime='',remoteAccess='';
try{remoteAccess=sessionStorage.getItem('prixrepere_connecteur_session')||''}catch{}
const el=id=>document.getElementById(id);
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('Impossible de sauvegarder : stockage plein. Exporte tes données.','error');return false}}
function toast(msg,type='ok'){const n=el('notice');n.textContent=msg;n.className='notice '+(type==='error'?'error':'');n.hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>n.hidden=true,5500)}
function cat(id){return state.categories.find(c=>c.id===id)||{id,name:'Catégorie inconnue',unit:'kg'}}
function store(id){return STORES.find(s=>s[0]===id)?.[1]||storeById(id)?.name||id}
function unit(p){return cat(p.category).unit}
function fresh(p,age=state.settings.maxAge){const a=dayAge(p.date);return a>=0&&a<=age}
function unitPrice(p){return N(p.packPrice)/N(p.packQty)}
function sourceLabel(p){return `${store(p.store)} · ${p.date}${fresh(p)?'':' · ancien prix'}`}
function sameRef(a,b){if(a.code&&b.code)return a.code===b.code;return a.name.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').trim()===b.name.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').trim()}
function currentPrices(){/* Un nouveau relevé remplace l'ancien pour le même article au même magasin. */
 const seen=new Set();return state.prices.filter(p=>STORES.some(s=>s[0]===p.store)).slice().sort((a,b)=>b.date.localeCompare(a.date)).filter(p=>{const ref=(p.code||p.name.toLowerCase().trim());const key=p.store+'|'+p.category+'|'+ref;if(seen.has(key))return false;seen.add(key);return true});}
function recentUnique(q,days=30){const map=new Map();q.filter(p=>fresh(p,days)).sort((a,b)=>b.date.localeCompare(a.date)).forEach(p=>{if(!map.has(p.store))map.set(p.store,p)});return [...map.values()]}
function median(arr){const a=arr.slice().sort((x,y)=>x-y);return a.length?(a[Math.floor((a.length-1)/2)]+a[Math.floor(a.length/2)])/2:null}
function quote(category,ref){let p=currentPrices().filter(x=>x.category===category&&(!ref||x.code===ref||(!x.code&&x.name.toLowerCase()===ref.toLowerCase())));let latest=recentUnique(p);return {n:latest.length,price:latest.length>=3?median(latest.map(unitPrice)):null}}
function verdict(price,cote){if(!cote||!isFinite(cote))return {text:'Cote insuffisante',tone:''};const diff=price/cote-1;return diff<=-.25?{text:'Très bonne affaire',tone:'green'}:diff<=-.1?{text:'Bonne affaire',tone:'green'}:diff<=.1?{text:'Prix normal',tone:''}:{text:'Prix élevé',tone:'red'}}
function selectCatsForScan(){return selectCats('','id="p-cat" required').replace('>', '><option value="" selected>Choisir le type de produit</option>')}
function selectCats(value='',extra=''){return `<select ${extra}>${state.categories.map(c=>`<option value="${E(c.id)}" ${value===c.id?'selected':''}>${E(c.name)} (${c.unit==='u'?'unité':c.unit})</option>`).join('')}</select>`}
function selectStores(value='u',extra=''){return `<select ${extra}>${STORES.length?STORES.map(s=>`<option value="${E(s[0])}" ${value===s[0]?'selected':''}>${E(s[1])}</option>`).join(''):'<option value="">Choisis des magasins dans Zone</option>'}</select>`}
function card(s,cls=''){return `<section class="card ${cls}">${s}</section>`}
function heading(t,d=''){return `<div class="eyebrow">${E(d||'PrixRepère')}</div><h1 class="h1">${E(t)}</h1>`}
function metric(label,value){return `<div class="metric"><small>${E(label)}</small><div class="big">${value}</div></div>`}
function go(t){tab=t;render();window.scrollTo(0,0)}
function render(){refreshStores();document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));el('app').innerHTML=({accueil:home,releve:releve,panier:panier,net:net,alertes:alertes,donnees:donnees,zone:zoneView})[tab]();el('area-header').textContent=areaText();bindTab()}
function home(){let prices=currentPrices().filter(p=>fresh(p));let count=state.list.length;let cheap=prices.filter(p=>{let q=quote(p.category);return q.price&&unitPrice(p)<=q.price*.75});let low=prices.reduce((m,p)=>!m||unitPrice(p)<unitPrice(m)?p:m,null);return `${heading('Compare tes courses. Économise vraiment.','Tableau de bord')}
${card(`<div class="row start"><div><div class="tag">Prix relevés encore récents</div><div style="font-size:42px;font-weight:850;letter-spacing:-2px">${prices.length}</div><div class="hint">Sur ${currentPrices().length} relevé(s) dans cette zone</div></div><span class="chip green">100 % personnel</span></div><div class="cols" style="margin-top:16px">${metric('Produits du panier',count)}${metric('Alertes programmées',state.alerts.length)}</div>`,'hero')}
<div class="quick-actions"><button id="go-releve"><span>📷</span>Scanner un prix</button><button id="go-panier"><span>🛒</span>Comparer mon panier</button><button id="go-net"><span>🌐</span>Comparer sur Internet</button></div>
<div class="section-title">Derniers prix enregistrés</div>${state.prices.length?card(currentPrices().slice(0,5).map(p=>`<div class="item row"><div><b>${E(cat(p.category).name)}</b><div class="hint">${E(sourceLabel(p))}</div></div><div style="text-align:right"><div class="money">${euro(unitPrice(p))}/${unit(p)==='u'?'u':unit(p)}</div><span class="chip ${fresh(p)?'green':'orange'}">${fresh(p)?'Récent':'Ancien'}</span></div></div>`).join('')):card('<div class="empty">Ajoute un premier prix pour commencer.</div>')}
${card(`<b>Zone active : ${E(areaText())}</b><p class="hint">Le panier, les alertes et la cote utilisent uniquement les magasins sélectionnés dans cette zone.</p><button class="btn secondary sm" id="go-zone-home">⌖ Modifier la zone et les magasins</button>`)}${card(`<b>Une vraie cote exige plusieurs relevés.</b><p class="hint">Pour éviter les faux « bons plans », PrixRepère n'affiche une cote catégorie qu'avec au moins 3 magasins distincts relevés depuis moins de 30 jours. Le premier tarif du poulet à 10,29 € vient de ta capture Super U.</p>`)}`}
function releve(){return `${heading('Scanne et juge une offre','Photo & scan')}
${card(`<div class="scan-step"><span class="scan-num">1</span><div><b>Photographie l’étiquette ou le prospectus</b><div class="hint">Tu peux aussi prendre le produit en photo : son code-barres aidera à l’identifier, mais le prix devra être visible sur l’étiquette.</div></div></div><div class="scan-actions"><label class="btn scan-action" for="photo-camera">📷 Prendre une photo</label><input id="photo-camera" type="file" accept="image/*" capture="environment" hidden><label class="btn secondary scan-action" for="photo-gallery">▧ Importer une image</label><input id="photo-gallery" type="file" accept="image/*" hidden></div><div id="photo-preview" class="scan-preview"></div><div class="scan-actions"><button id="ocr" class="btn secondary scan-action" disabled>◉ Lire le texte de la photo</button><button id="barcode-scan" class="btn ghost scan-action" disabled>▥ Lire un code-barres</button></div><p id="ocr-status" class="hint" role="status">La lecture OCR nécessite Internet la première fois. La photo reste sur ton appareil ; l’OCR est effectué localement par le navigateur.</p><div id="scan-results" class="scan-results" aria-live="polite"></div>`) }
${card(`<div class="scan-step"><span class="scan-num">2</span><div><b>Vérifie les informations détectées</b><div class="hint">Ne valide jamais un prix ancien, un prix au kilo ou une remise fidélité comme s’il s’agissait du prix total payé.</div></div></div><form id="price-form"><div class="field"><label>Type de produit</label>${selectCatsForScan()}</div><div class="field"><label>Produit / marque</label><input id="p-name" required maxlength="140" value="" placeholder="Ex. filet de poulet Prix Mini"></div><div class="field"><label>Code-barres (si visible)</label><div class="row"><input id="p-code" inputmode="numeric" placeholder="EAN facultatif"><button type="button" class="btn secondary sm" id="lookup-off">Identifier</button></div></div><div class="field"><label>Magasin du relevé</label>${selectStores('u','id="p-store"')}</div><div class="field-grid"><div class="field"><label>Quantité totale du lot</label><input id="p-qty" required type="number" min="0.001" step="any" placeholder="Ex. 500"></div><div class="field"><label>Unité affichée</label><select id="p-unit"><option value="kg">kg</option><option value="g">g</option><option value="L">L</option><option value="ml">ml</option><option value="u">unité(s)</option></select></div></div><p class="hint">Pour 2 × 250 g, renseigne 500 g, ou 0,5 kg. Pour une promotion en lot, saisis le prix TOTAL des articles nécessaires pour en bénéficier.</p><div class="field-grid"><div class="field"><label>Prix TOTAL de l’offre (€)</label><input id="p-price" required type="text" inputmode="decimal" placeholder="Ex. 7,90"></div><div class="field"><label>Date du prix</label><input id="p-date" required type="date" value="${today()}"></div></div><div class="field"><label>Conditions, restrictions et fidélité</label><textarea id="p-comment" placeholder="Ex. 2e à -50 %, remise immédiate, carte fidélité…"></textarea></div><label class="scan-check"><input type="checkbox" id="scan-verified"><span>J’ai vérifié le prix total, la quantité, et les conditions éventuelles de l’offre photographiée.</span></label><div id="price-calc" class="price-readout" aria-live="polite">Saisis le prix et la quantité pour afficher le verdict.</div><div class="scan-step" style="margin-top:14px"><span class="scan-num">3</span><div><b>Enregistre le relevé</b><div class="hint">Il enrichira tes comparaisons, ton panier et tes alertes.</div></div></div><button class="btn wide" type="submit">✓ Enregistrer le prix vérifié</button></form>`)}
${card(`<b>Comment interpréter le verdict ?</b><p class="hint">Une cote fiable demande au minimum des relevés récents dans trois magasins différents. Sans suffisamment de données, l’application calcule le prix unitaire mais annonce « Cote insuffisante », jamais une fausse bonne affaire. La photo n’est pas enregistrée.</p>`)} `}
function itemMatches(p,item){if(p.category!==item.category||!fresh(p)||p.packUsable===false)return false;if(!item.exact)return true;return p.code===item.exact||p.name.toLowerCase().trim()===item.exact.toLowerCase().trim()}
/* Minimum exact par produit en combinant les conditionnements, sans fractionner les packs.
   Quantités discrétisées au gramme/millilitre et prix au centime. */
function optimizeItem(item,onlyStore=null){const c=cat(item.category),factor=c.unit==='u'?1:1000,goal=Math.round(N(item.qty)*factor);if(!Number.isFinite(goal)||goal<1||goal>35000)return {error:'Quantité hors plage (maximum 35 kg/L ou 35 unités).'};let opts=currentPrices().filter(p=>itemMatches(p,item)&&(!onlyStore||p.store===onlyStore)).map(p=>({p,q:Math.round(N(p.packQty)*factor),cost:Math.round(N(p.packPrice)*100)})).filter(x=>x.q>0&&x.cost>0&&x.q<=35000);if(!opts.length)return {missing:true};const bound=goal+Math.max(...opts.map(o=>o.q))-1;if(bound>70000)return {error:'Conditionnement trop grand pour le calcul.'};let costs=new Float64Array(bound+1).fill(Infinity),prev=new Int32Array(bound+1).fill(-1),used=new Int16Array(bound+1).fill(-1);costs[0]=0;for(let i=1;i<=bound;i++){for(let k=0;k<opts.length;k++){const o=opts[k];if(i<o.q)continue;const before=costs[i-o.q];const cand=before+o.cost;if(cand<costs[i]){costs[i]=cand;prev[i]=i-o.q;used[i]=k}}}let best=-1;for(let i=goal;i<=bound;i++)if(best<0||costs[i]<costs[best])best=i;if(best<0||!isFinite(costs[best]))return {missing:true};const counts=new Map();let curr=best;let guard=0;while(curr>0&&guard++<bound){const j=used[curr];if(j<0)break;const id=opts[j].p.id;counts.set(id,(counts.get(id)||0)+1);curr=prev[curr]}const groups=[...counts].map(([id,n])=>({price:state.prices.find(p=>p.id===id),packs:n}));return {cost:costs[best]/100,qty:best/factor,parts:groups}}
function calcBasket(){let rows=state.list.map(item=>({item,ans:optimizeItem(item)}));let valid=rows.every(x=>Number.isFinite(x.ans.cost));let byStore=[];for(const [id,name] of STORES){let result=state.list.map(item=>optimizeItem(item,id));if(result.every(x=>Number.isFinite(x.cost)))byStore.push({id,name,cost:result.reduce((s,r)=>s+r.cost,0)})}byStore.sort((a,b)=>a.cost-b.cost);let byStoreUsed={};for(const {ans} of rows)if(ans.parts)for(const part of ans.parts){const id=part.price.store;byStoreUsed[id]=(byStoreUsed[id]||0)+part.packs*part.price.packPrice}return {rows,valid,total:rows.reduce((s,r)=>s+(r.ans.cost||0),0),byStore,bestSingle:byStore[0]||null,byStoreUsed}}
function panier(){const b=calcBasket();return `${heading('Le panier le moins cher','Mes courses')}
${card(`<div class="row start"><div><b>Ma liste de courses</b><p class="hint">Le calcul autorise autant de magasins que nécessaire et combine les formats pour minimiser le montant payé.</p></div><span class="chip">${state.list.length} articles</span></div><form id="add-item"><div class="field-grid"><div class="field"><label>Produit</label>${selectCats('poulet','id="item-cat"')}</div><div class="field"><label>Quantité demandée</label><input type="number" step="any" min="0.001" id="item-qty" value="1" required></div></div><div class="field"><label>Produit exact (nom ou EAN, facultatif)</label><input id="item-exact" placeholder="Vide = toutes marques équivalentes"></div><button class="btn secondary sm" type="submit">+ Ajouter à ma liste</button></form><hr class="divider">${state.list.length?state.list.map(x=>`<div class="item row"><div><b>${E(cat(x.category).name)}</b><div class="hint">${num(x.qty,3)} ${cat(x.category).unit}${x.exact?' · Exact : '+E(x.exact):' · Toutes marques'}</div></div><button class="btn danger sm" data-remove-item="${E(x.id)}">Retirer</button></div>`).join(''):'<div class="empty">Ajoute des produits à ta liste.</div>'}`)}
${card(`<div class="tag">Meilleur panier calculable</div><div class="row"><div style="font-size:34px;font-weight:850;color:#146f50">${b.valid&&b.rows.length?euro(b.total):'Incomplet'}</div>${b.valid&&b.rows.length?'<span class="chip green">Coût minimal d’achat</span>':''}</div>${b.rows.length?`<p class="hint">${b.rows.filter(x=>Number.isFinite(x.ans.cost)).length}/${b.rows.length} produits couverts par des prix de moins de ${state.settings.maxAge} jours.</p>`:'<p class="hint">Ta liste est vide.</p>'}${b.valid&&b.bestSingle&&b.rows.length?`<div class="reco"><b>Économie par rapport au meilleur magasin unique :</b><div class="money positive" style="font-size:20px">${euro(b.bestSingle.cost-b.total)}</div><div class="hint">Meilleur magasin unique : ${E(b.bestSingle.name)} (${euro(b.bestSingle.cost)}).</div></div>`:b.valid?'<p class="hint">Aucun magasin ne couvre à lui seul tous les produits avec nos relevés actuels.</p>':'<div class="chip orange">Prix manquants : impossible d’annoncer un gagnant fiable.</div>'}`)}
${b.rows.map(({item,ans})=>card(`<div class="row"><b>${E(cat(item.category).name)} · ${num(item.qty,3)} ${cat(item.category).unit}</b><b class="money">${Number.isFinite(ans.cost)?euro(ans.cost):'<span class="chip orange">À compléter</span>'}</b></div>${ans.parts?ans.parts.map(x=>`<div class="item"><div class="row"><div class="small"><b>${E(store(x.price.store))}</b> · ${E(x.price.name)}<div class="hint">${x.packs} × ${num(x.price.packQty,3)} ${cat(item.category).unit} · ${x.price.date}</div></div><b class="nowrap small">${euro(x.packs*x.price.packPrice)}</b></div></div>`).join(''):`<p class="hint">${E(ans.error||'Pas de prix récent pour ce produit dans les magasins sélectionnés.')}</p>`}${ans.parts&&ans.qty>item.qty?`<div class="hint">Quantité réellement achetée : ${num(ans.qty,3)} ${cat(item.category).unit} (conditionnements indivisibles).</div>`:''}`)).join('')}
${b.valid&&b.rows.length?`<div class="section-title">Ma tournée, magasin par magasin</div>${Object.entries(b.byStoreUsed).sort((a,b)=>b[1]-a[1]).map(([s,t])=>card(`<div class="row"><b>${E(store(s))}</b><b>${euro(t)}</b></div>${b.rows.flatMap(x=>(x.ans.parts||[]).filter(p=>p.price.store===s).map(p=>`<div class="hint" style="margin-top:8px">☑ ${E(cat(x.item.category).name)} · ${p.packs} pack(s)</div>`)).join('')}`)).join('')}`:''}
${card(`<b>Calcul des déplacements</b><p class="hint">Cette version minimise d'abord le coût des achats, sans limiter le nombre de magasins. Les kilomètres, le carburant et le temps de trajet ne sont pas déduits du total.</p>`)}`}

/* PrixRepère v1.2 : recherche ponctuelle d'offres web, calcul livraison comprise.
   Le navigateur n'interroge PAS silencieusement les catalogues des vendeurs :
   extraction fiable et livraison par adresse nécessitent des accès de données autorisés.
*/
function onlineTotals(o,qty){
 const quantity=N(qty),pack=N(o.packQty),price=N(o.packPrice),ship=N(o.shippingFee),free=N(o.freeFrom);
 if(!(quantity>0&&pack>0&&price>0)||!Number.isFinite(quantity)||!Number.isFinite(pack)||!Number.isFinite(price))return {error:'Prix ou quantité invalides'};
 const packs=Math.ceil((quantity-0.0000001)/pack);
 if(packs<1||packs>300)return {error:'Quantité trop importante'};
 const products=Math.round(packs*price*100)/100;
 const postage=o.shippingMode==='unknown'?null:(o.shippingMode==='free'||(o.shippingMode==='threshold'&&free>0&&products+1e-9>=free)?0:ship);
 if(postage!==null&&(!Number.isFinite(postage)||postage<0))return {error:'Livraison invalide'};
 return {packs,products,shipping:postage,total:postage===null?null:Math.round((products+postage)*100)/100,unitCost:postage===null?null:(products+postage)/(packs*pack),actualQty:packs*pack};
}
function onlineCompare(category,qty,exact=''){
 const q=N(qty),x=String(exact||'').trim().toLowerCase();
 const all=state.onlineOffers.filter(o=>o.category===category&&(!x||o.code===exact||o.name.toLowerCase().trim()===x));
 const rows=all.map(o=>({offer:o,...onlineTotals(o,q),isFresh:fresh(o)}));
 const ranked=rows.filter(r=>r.isFresh&&r.total!==null&&Number.isFinite(r.total)).sort((a,b)=>a.total-b.total);
 const local=optimizeItem({category,qty:q,exact},null);
 return {rows,ranked,local};
}

function renderRemoteOffers(baseUnit,qty){
 if(!remoteOffers.length)return '<div class="empty">Aucune offre reçue. Connecte le service puis lance une recherche à la demande.</div>';
 const rows=remoteOffers.map((o,i)=>{
  const compatible=o.unit===baseUnit&&Number.isFinite(o.packQty)&&o.packQty>0;
  const calc=compatible?onlineTotals({packQty:o.packQty,packPrice:o.price,shippingMode:o.shippingMode,shippingFee:o.shippingFee,freeFrom:0},qty):null;
  const delivery=calc&&calc.total!==null?`<b>${euro(calc.total)} livré <span style="font-size:11px">(indicatif)</span></b>`:'<span class="chip orange">Port ou format à confirmer</span>';
  const href=o.url&&/^https:\/\//i.test(o.url)?`<a href="${E(o.url)}" target="_blank" rel="noopener noreferrer" class="mini-link">↗ Voir l’offre</a>`:'';
  return `<div class="item"><div class="row start"><div style="min-width:0"><b>${E(o.title)}</b><div class="hint">${E(o.seller)} · Produit : ${euro(o.price)}${compatible?' · '+num(o.packQty,3)+' '+baseUnit:' · Format non détecté'}</div><div class="hint">Livraison affichée : ${E(o.deliveryText||'non indiquée')} — à vérifier pour ton adresse</div></div><div style="text-align:right;min-width:113px">${delivery}</div></div><div class="row">${href}<button class="btn secondary sm" type="button" data-auto-copy="${i}">Reprendre l'offre</button></div></div>`;
 }).join('');
 return '<p class="hint"><b>'+remoteOffers.length+' offre(s)</b> trouvée(s) — résultats du moteur de recherche, non vérifiés au panier. Le total provisoire utilise la quantité demandée et les seuls frais explicitement affichés. Aucune offre ne devient « gagnante » sans contrôle.</p>'+rows;
}
