function defaultPackUnit(){const c=cat(el('p-cat').value);el('p-unit').value=c.unit}
function getFormNumbers(){const q=N(el('p-qty').value),price=N(el('p-price').value),given=el('p-unit').value,u=cat(el('p-cat').value).unit;let factor=1;if(u==='kg'&&given==='g'||u==='L'&&given==='ml')factor=.001;else if(u!==given)factor=NaN;return {q:q*factor,price,u}}
function updatePrice(){
 const {q,price,u}=getFormNumbers(),box=el('price-calc');if(!box)return;
 const c=el('p-cat').value,code=el('p-code').value.trim(),name=el('p-name').value.trim();
 const valid=!!c&&Number.isFinite(q)&&q>0&&Number.isFinite(price)&&price>0;
 if(!valid){box.innerHTML='<b>En attente du prix total et du poids / volume</b><div class="hint">Tu peux vérifier le prix sans enregistrer l’offre.</div>';return}
 const total=price/q,categoryCote=quote(c),exactCote=quote(c,code||name),v=verdict(total,categoryCote.price);
 const pct=cote=>cote?` <small>(${num((total/cote-1)*100,1)} %)</small>`:'';
 box.innerHTML=`<div class="tag">Prix réel de ton offre</div><div class="scan-result-value">${euro(total)}/${E(u)}</div><div class="scan-verdict ${E(v.tone)}">${E(v.text)}</div><div class="hint" style="margin-top:7px">${categoryCote.price?'Cote catégorie : '+euro(categoryCote.price)+'/'+E(u)+pct(categoryCote.price):'Cote catégorie : données insuffisantes ('+categoryCote.n+'/3 magasins)'}</div><div class="hint">${exactCote.price?'Cote du produit exact : '+euro(exactCote.price)+'/'+E(u)+pct(exactCote.price):'Cote du produit exact : données insuffisantes ('+exactCote.n+'/3 magasins)'}</div>`;
}
function setAmountFromOCR(text){
 if(!window.PriceScan){toast('Analyseur non chargé. Tu peux saisir le relevé.','error');return}
 scanResult=PriceScan.analyze(text);scanPromoNeedsConfirm=scanResult.complex;
 if(scanResult.category&&state.categories.some(x=>x.id===scanResult.category)){el('p-cat').value=scanResult.category;defaultPackUnit()}
 if(scanResult.name)el('p-name').value=scanResult.name;
 if(scanResult.code)el('p-code').value=scanResult.code;
 if(scanResult.pack)applyScanSize(scanResult.pack);
 if(scanResult.price)el('p-price').value=String(scanResult.price.value).replace('.',',');
 if(scanResult.promo){el('p-comment').value=(el('p-comment').value+' | Texte promo : '+text.slice(0,400)).replace(/^\s*\|\s*/, '').trim()}
 el('scan-verified').checked=false;
 displayScanResults();updatePrice();
}
function applyScanSize(size){const c=cat(el('p-cat').value);if(size.unit!==c.unit){el('p-qty').value='';toast('Unité lue différente de celle de la catégorie. Vérifie manuellement.','error');return}
 el('p-qty').value=size.quantity;el('p-unit').value=c.unit;
}
function displayScanResults(){const a=scanResult,div=el('scan-results');if(!div||!a)return;
 const candidates=a.prices.filter(p=>!p.unitPrice&&!p.wasPrice);
 const extras=a.prices.filter(p=>p.unitPrice);
 div.innerHTML=`<div class="scan-insight"><b>Texte analysé — contrôle nécessaire</b><p class="hint">Produit probable : ${E(a.name||'non identifié')}${a.category?' · '+E(cat(a.category).name):''}</p>${a.warnings.map(w=>`<div class="scan-warning">⚠ ${E(w)}</div>`).join('')}<div class="hint" style="margin-top:9px"><b>Prix totaux détectés (touche le bon)</b></div><div class="scan-chips">${candidates.length?candidates.map((x,i)=>`<button class="scan-chip" type="button" data-scan-price="${i}">${euro(x.value)} ${x.wasPrice?'ancien':''}</button>`).join(''):'<span class="hint">Aucun prix total fiable</span>'}</div>${extras.length?`<p class="hint">Prix unitaires vus sur l’étiquette (pas appliqués comme prix du paquet) : ${extras.map(p=>euro(p.value)).join(' · ')}</p>`:''}<div class="hint"><b>Conditionnements détectés</b></div><div class="scan-chips">${a.sizes.length?a.sizes.map((x,i)=>`<button type="button" class="scan-chip" data-scan-size="${i}">${E(x.raw)} → ${num(x.quantity,3)} ${E(x.unit)}</button>`).join(''):'<span class="hint">Aucun ; renseigne la quantité</span>'}</div><details class="scan-raw"><summary>Voir le texte lu par l’OCR</summary><pre>${E(a.text)}</pre></details></div>`;
 div.querySelectorAll('[data-scan-price]').forEach(btn=>btn.onclick=()=>{const p=candidates[+btn.dataset.scanPrice];if(p){el('p-price').value=String(p.value).replace('.',',');el('scan-verified').checked=false;updatePrice()}});
 div.querySelectorAll('[data-scan-size]').forEach(btn=>btn.onclick=()=>{const size=a.sizes[+btn.dataset.scanSize];if(size){applyScanSize(size);el('scan-verified').checked=false;updatePrice()}});
}
async function doOCR(){
 if(!scannedImage){toast('Choisis une photo d’abord.','error');return}if(ocrBusy)return;
 ocrBusy=true;el('ocr').disabled=true;el('ocr-status').textContent='Chargement du moteur OCR français…';
 try{
  if(!window.Tesseract)await new Promise((resolve,reject)=>{const sc=document.createElement('script');sc.src='https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js';sc.onload=resolve;sc.onerror=()=>reject(Error('OCR indisponible : connexion Internet nécessaire.'));document.head.appendChild(sc)});
  el('ocr-status').textContent='Lecture locale en cours, quelques secondes…';const worker=await Tesseract.createWorker('fra');
  try{const result=await worker.recognize(scannedImage),t=result?.data?.text||'';if(!t.trim())throw Error('Aucun texte lisible. Reprends la photo de plus près.');setAmountFromOCR(t);el('ocr-status').textContent='Lecture terminée. Sélectionne les bonnes valeurs, puis valide.';toast('Photo analysée. Vérifie le prix et la quantité.')}finally{await worker.terminate()}
 }catch(err){el('ocr-status').textContent=String(err?.message||'Lecture impossible')+'. Tu peux renseigner le relevé manuellement.';toast('Lecture OCR non disponible : saisie manuelle possible.','error')}
 finally{ocrBusy=false;el('ocr').disabled=!scannedImage}
}
async function doScanBarcode(){
 if(!scannedImage){toast('Sélectionne une photo.','error');return}
 if(!('BarcodeDetector'in window)){toast('Lecture du code-barres indisponible sur ce navigateur. Saisie manuelle possible.','error');return}
 const btn=el('barcode-scan');btn.disabled=true;
 try{const detector=new BarcodeDetector({formats:['ean_13','ean_8','upc_a']});const bmp=await createImageBitmap(scannedImage);let found;try{found=await detector.detect(bmp)}finally{bmp.close?.()}
  if(!found?.length)throw Error('Aucun code-barres détecté sur cette photo.');
  const value=String(found[0].rawValue||'');if(!/^\d{8,14}$/.test(value))throw Error('Code-barres non reconnu.');
  el('p-code').value=value;updatePrice();toast('Code-barres lu : '+value+'. Identification du produit à vérifier.');await doBarcodeLookup();
 }catch(err){toast(err.message||'Impossible de lire le code-barres.','error')}finally{btn.disabled=!scannedImage}
}
function onScanFile(f){
 if(!f)return;if(!f.type.startsWith('image/')){toast('Choisis une image (JPG, PNG, HEIC selon ton navigateur).','error');return}
 if(f.size>18e6){toast('Image supérieure à 18 Mo. Prends une photo moins lourde.','error');return}
 scannedImage=f;scanResult=null;scanPromoNeedsConfirm=false;el('scan-verified').checked=false;
 el('p-name').value='';el('p-code').value='';el('p-cat').value='';el('p-qty').value='';el('p-price').value='';el('p-comment').value='';el('p-unit').value='kg';updatePrice();
 if(scanImageUrl)URL.revokeObjectURL(scanImageUrl);scanImageUrl=URL.createObjectURL(f);
 el('photo-preview').innerHTML=`<img src="${E(scanImageUrl)}" alt="Photo sélectionnée, prête à analyser">`;
 el('ocr').disabled=false;el('barcode-scan').disabled=false;el('scan-results').innerHTML='';
 el('ocr-status').textContent='Photo chargée. Choisis « Lire le texte » pour reconnaître les tarifs, ou « Lire un code-barres ».';
}
async function doBarcodeLookup(){const code=el('p-code').value.trim();if(!/^\d{8,14}$/.test(code)){toast('Saisis un code-barres de 8 à 14 chiffres.','error');return}const b=el('lookup-off');b.disabled=true;b.textContent='Recherche…';try{const r=await fetch('https://world.openfoodfacts.org/api/v2/product/'+encodeURIComponent(code)+'?fields=product_name,brands,quantity',{headers:{Accept:'application/json'}});if(!r.ok)throw Error('API indisponible');const x=await r.json();if(!x.product||!x.product.product_name){toast('Produit non trouvé dans Open Food Facts.','error');return}el('p-name').value=[x.product.brands,x.product.product_name].filter(Boolean).join(' — ');let q=String(x.product.quantity||'').match(/([\d.,]+)\s*(kg|g|ml|cl|l)\b/i);if(q){el('p-qty').value=N(q[1]);el('p-unit').value=q[2].toLowerCase()==='l'?'L':q[2].toLowerCase()==='cl'?'L':q[2].toLowerCase();if(q[2].toLowerCase()==='cl')el('p-qty').value=N(q[1])/100}updatePrice();toast('Produit identifié. Confirme la catégorie et le prix.')}catch{toast('Recherche impossible actuellement. Saisie manuelle possible.','error')}finally{b.disabled=false;b.textContent='Identifier'}}
function pushNotice(title,detail,id){if(state.notices.some(n=>n.id===id))return;state.notices.unshift({id,title,detail,date:today()});state.notices=state.notices.slice(0,80);if('Notification'in window&&Notification.permission==='granted'){try{new Notification('PrixRepère · '+title,{body:detail,icon:'icon.svg',tag:id})}catch{}}toast(title+' — '+detail)}
function checkAlerts(){let changed=false;for(const a of state.alerts){const candidates=currentPrices().filter(p=>fresh(p)&&p.category===a.category&&(!a.exact||p.code===a.exact||p.name.toLowerCase().trim()===a.exact.toLowerCase().trim()));const cote=quote(a.category).price;for(const p of candidates){const pr=unitPrice(p);const meets=a.kind==='target'?pr<=a.value:!!cote&&pr<=cote*(1-a.value/100);if(!meets)continue;const key=a.id+'@'+p.id;if(state.notices.some(n=>n.id===key))continue;pushNotice(`${cat(a.category).name} à ${euro(pr)}/${cat(a.category).unit}`,`${store(p.store)} · relevé du ${p.date} · ${a.kind==='target'?'sous ton prix cible':'sous la cote'}`,key);changed=true}}if(changed)persist()}
function savePriceRecord(p){if(!Number.isFinite(N(p.packPrice))||N(p.packPrice)<=0||!Number.isFinite(N(p.packQty))||N(p.packQty)<=0||!p.name||!state.categories.some(c=>c.id===p.category)||!STORES.some(s=>s[0]===p.store)){toast('Prix, quantité, catégorie, produit ou magasin invalides.','error');return false}state.prices.unshift(p);persist();checkAlerts();return true}
function bindTab(){if(tab==='accueil'){el('go-releve').onclick=()=>go('releve');el('go-panier').onclick=()=>go('panier');el('go-net').onclick=()=>go('net');el('go-zone-home').onclick=()=>go('zone')}
if(tab==='releve'){
 el('p-cat').addEventListener('change',()=>{defaultPackUnit();updatePrice()});['p-qty','p-unit','p-price','p-name','p-code'].forEach(id=>el(id).addEventListener('input',updatePrice));
 el('photo-camera').addEventListener('change',e=>onScanFile(e.target.files?.[0]));
 el('photo-gallery').addEventListener('change',e=>onScanFile(e.target.files?.[0]));
 el('ocr').onclick=doOCR;el('barcode-scan').onclick=doScanBarcode;el('lookup-off').onclick=doBarcodeLookup;
 updatePrice();el('price-form').onsubmit=e=>{e.preventDefault();if(scannedImage&&!el('scan-verified').checked){toast('Confirme d’abord avoir vérifié les valeurs de la photo.','error');el('scan-verified').focus();return}const {q,price}=getFormNumbers();const p={id:uid(),category:el('p-cat').value,store:el('p-store').value,name:el('p-name').value.trim(),code:el('p-code').value.trim(),packQty:q,packPrice:price,date:el('p-date').value,source:scannedImage?'Photo / relevé utilisateur':'Relevé utilisateur',comment:el('p-comment').value.trim()};if(!/^\d{4}-\d{2}-\d{2}$/.test(p.date)||dayAge(p.date)<0){toast('La date ne doit pas être dans le futur.','error');return}if(savePriceRecord(p)){scannedImage=null;scanResult=null;if(scanImageUrl){URL.revokeObjectURL(scanImageUrl);scanImageUrl=''}go('donnees');toast(`Enregistré : ${euro(price/q)}/${cat(p.category).unit} chez ${store(p.store)}.`)}};
 }
if(tab==='panier'){
 el('add-item').onsubmit=e=>{e.preventDefault();const c=el('item-cat').value,q=N(el('item-qty').value);if(!q||q<=0||q>35){toast('Quantité entre 0 et 35.','error');return}state.list.push({id:uid(),category:c,qty:q,exact:el('item-exact').value.trim()});persist();render();toast('Produit ajouté au panier.')};document.querySelectorAll('[data-remove-item]').forEach(btn=>btn.onclick=()=>{state.list=state.list.filter(i=>i.id!==btn.dataset.removeItem);persist();render()})}
if(tab==='alertes'){
 el('a-kind').onchange=()=>{el('a-lab').textContent=el('a-kind').value==='target'?'Prix cible (€/kg, €/L ou /u)':'Baisse minimale (%)';el('a-val').value=el('a-kind').value==='target'?'7,90':'25'};
 el('alert-form').onsubmit=e=>{e.preventDefault();const v=N(el('a-val').value);if(!isFinite(v)||v<=0||(el('a-kind').value==='drop'&&v>=100)){toast('Valeur d’alerte invalide.','error');return}state.alerts.push({id:uid(),category:el('a-cat').value,kind:el('a-kind').value,value:v,exact:el('a-exact').value.trim(),lastKey:''});persist();checkAlerts();render();toast('Alerte créée.')};document.querySelectorAll('[data-remove-alert]').forEach(b=>b.onclick=()=>{state.alerts=state.alerts.filter(a=>a.id!==b.dataset.removeAlert);persist();render()});
 el('enable-notifications').onclick=async()=>{if(!('Notification'in window)){toast('Ce navigateur ne permet pas les notifications locales.','error');return}try{let p=await Notification.requestPermission();toast(p==='granted'?'Notifications autorisées pendant l’utilisation.':'Notifications non autorisées.') }catch{toast('Autorisation impossible sur ce navigateur.','error')}};
 }
if(tab==='net'){bindNet()}
if(tab==='zone'){bindZone()}
if(tab==='donnees'){
 document.querySelectorAll('[data-remove-price]').forEach(b=>b.onclick=()=>{if(!confirm('Supprimer ce prix ?'))return;state.prices=state.prices.filter(p=>p.id!==b.dataset.removePrice);persist();render()});
 el('cat-form').onsubmit=e=>{e.preventDefault();const name=el('c-name').value.trim();if(!name||state.categories.some(c=>c.name.toLowerCase()===name.toLowerCase())){toast('Nom déjà utilisé ou vide.','error');return}state.categories.push({id:uid(),name,unit:el('c-unit').value});persist();render();toast('Catégorie ajoutée.')};
 el('max-age').onchange=e=>{state.settings.maxAge=+e.target.value;persist();render();toast('Durée de validité actualisée.')};
 el('export').onclick=exportData;el('import').onchange=importData;
 el('open-form').onsubmit=searchOpenPrices;
 }
}
async function searchOpenPrices(e){e.preventDefault();const out=el('open-results'),code=el('open-code').value.trim(),b=e.target.querySelector('button');if(code&&!/^\d{8,14}$/.test(code)){toast('Le code-barres doit contenir entre 8 et 14 chiffres.','error');return}const u=new URL('https://prices.openfoodfacts.org/api/v1/prices');u.searchParams.set('currency','EUR');u.searchParams.set('size','50');u.searchParams.set('order_by','-date');u.searchParams.set('date__gte',new Date(Date.now()-90*86400000).toISOString().slice(0,10));if(code)u.searchParams.set('product_code',code);else{if(!Number.isFinite(activeZone().lat)||!Number.isFinite(activeZone().lon))throw Error('Définis une zone géographique dans l’onglet Zone.');u.searchParams.set('lat',String(activeZone().lat));u.searchParams.set('lon',String(activeZone().lon));u.searchParams.set('radius_km',String(activeZone().radius))};out.innerHTML='Recherche en cours…';b.disabled=true;
 try{const r=await fetch(u.toString(),{headers:{Accept:'application/json'}});if(!r.ok)throw Error('HTTP '+r.status);const payload=await r.json();externalPrices=Array.isArray(payload.items)?payload.items:[];out.innerHTML=externalPrices.length?`<p>${externalPrices.length} résultat(s) reçus. Les prix doivent être vérifiés avant importation.</p>`+externalPrices.slice(0,30).map((p,i)=>{let nm=p.product?.product_name||p.product_name||'Produit sans nom',location=p.location?.osm_display_name||p.location?.osm_name||'Magasin non précisé';return `<div class="openpricesitem"><b>${E(nm)}</b><p class="small">${euro(p.price||0)} · ${E(p.price_per||'UNIT')} · ${E(p.date||'Date inconnue')}<br>${E(location)}</p><div class="field"><label>Catégorie attribuée</label>${selectCats('poulet',`id="op-cat-${i}"`)}</div><div class="field"><label>Magasin vérifié</label><select id="op-store-${i}"><option value="">— Je confirme le magasin —</option>${STORES.map(s=>`<option value="${s[0]}">${E(s[1])}</option>`).join('')}</select></div><button class="btn secondary sm" data-import-op="${i}">Importer ce prix vérifié</button></div>`}).join(''):'<div class="empty">Aucun prix trouvé pour cette recherche. Tu peux enregistrer le prix manuellement.</div>';out.querySelectorAll('[data-import-op]').forEach(x=>x.onclick=()=>importOpen(x.dataset.importOp))}catch(error){out.innerHTML=`<p class="negative">Impossible d'accéder à Open Prices depuis cet appareil (${E(error.message)}). La saisie manuelle reste opérationnelle.</p>`}finally{b.disabled=false}}
function importOpen(idx){const i=+idx,p=externalPrices[i];if(!p)return;const storeId=el('op-store-'+i).value,category=el('op-cat-'+i).value,u=cat(category).unit;if(!storeId){toast('Choisis le magasin après vérification du lieu relevé.','error');return}let qty=NaN,packPrice=N(p.price),per=p.price_per||'UNIT';if(per==='KILOGRAM'&&u==='kg')qty=1;else if(per==='LITER'&&u==='L')qty=1;else if(per==='UNIT'){
 if(u==='u')qty=1;else{const product=p.product||{};let matches=String(product.quantity||'').match(/([\d.,]+)\s*(kg|g|ml|cl|l)\b/i);let unit=matches?.[2]?.toLowerCase(),n=matches?N(matches[1]):NaN;if(!matches&&product.product_quantity&&product.product_quantity_unit){n=N(product.product_quantity);unit=String(product.product_quantity_unit).toLowerCase()}if(u==='kg'&&(unit==='g'||unit==='kg'))qty=n*(unit==='g'?.001:1);if(u==='L'&&['ml','cl','l'].includes(unit))qty=n*(unit==='ml'?.001:unit==='cl'?.01:1)}
}if(!(qty>0)){toast('Conditionnement non déterminé. Relève ce produit manuellement.','error');return}const record={id:uid(),category,store:storeId,name:p.product?.product_name||p.product_name||'Relevé Open Prices',code:p.product_code||'',packQty:qty,packPrice,date:p.date,source:'Open Prices #'+p.id,comment:'Import après vérification manuelle du magasin. Source ouverte : Open Prices (ODbL).'};if(savePriceRecord(record)){toast('Prix importé.');render()}}
function exportData(){const blob=new Blob([JSON.stringify({format:'prixrepere-v1.3',exported:today(),...state},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='PrixRepere_sauvegarde_'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),5000)}
async function importData(e){const f=e.target.files?.[0];if(!f)return;try{if(f.size>5e6)throw Error('Fichier trop volumineux.');const incoming=JSON.parse(await f.text());if(!Array.isArray(incoming.categories)||!Array.isArray(incoming.prices)||!Array.isArray(incoming.list)||!Array.isArray(incoming.alerts))throw Error('Ce fichier n’est pas une sauvegarde valide de PrixRepère.');if(!confirm('Restaurer cette sauvegarde ? Cela remplace les données présentes sur cet appareil.'))return;state={...initial(),...incoming,categories:[...incoming.categories,...BASECATS.filter(c=>!incoming.categories.some(xc=>xc.id===c.id))],onlineOffers:Array.isArray(incoming.onlineOffers)?incoming.onlineOffers:[],settings:{...initial().settings,...incoming.settings},zones:normalizeZones(incoming.zones),activeZone:['home','holiday'].includes(incoming.activeZone)?incoming.activeZone:'home'};refreshStores();persist();render();toast('Sauvegarde restaurée.')}catch(err){toast(err.message||'Impossible de restaurer le fichier.','error')}}

/* ZONES V1.3 — préférences d'achat par zone et prix associés à des magasins OpenStreetMap.
   Découverte volontaire (Overpass, Nominatim), recherche de relevés volontaires (Open Prices).
   Aucune extraction directe ni promesse de prix exhaustifs depuis les Drives privés. */
function distKm(a,b,c,d){const R=6371,rad=Math.PI/180,dlat=(c-a)*rad,dlon=(d-b)*rad,v=Math.sin(dlat/2)**2+Math.cos(a*rad)*Math.cos(c*rad)*Math.sin(dlon/2)**2;return R*2*Math.atan2(Math.sqrt(v),Math.sqrt(1-v))}
function cleanZoneName(x){return String(x||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function zoneView(){const z=activeZone();return `${heading('Zone de recherche et magasins','Périmètre de tes courses')}
${card(`<div class="row"><b>Profil actif</b><span class="chip green">${E(z.label)}</span></div><div class="field-grid" style="margin-top:12px"><button id="area-home" class="btn ${state.activeZone==='home'?'':'secondary'}">⌂ Maison</button><button id="area-holiday" class="btn ${state.activeZone==='holiday'?'':'secondary'}">☀ Vacances</button></div><p class="hint">Chaque profil conserve ses magasins. Tu peux passer de Vacances à Maison sans effacer tes relevés.</p>`)}
${card(`<form id="area-form"><div class="field"><label>Ville / commune / code postal</label><input id="area-place" value="${E(z.place||'')}" placeholder="Ex. Le Lavandou 83980" required maxlength="120"></div><div class="field"><label>Rayon de recherche</label><select id="area-radius">${[5,10,15,20,25,30,40,50].map(n=>`<option value="${n}" ${z.radius===n?'selected':''}>${n} km</option>`).join('')}</select></div><div class="row" style="flex-wrap:wrap"><button type="submit" class="btn">📍 Rechercher cette ville</button><button id="area-gps" type="button" class="btn secondary">Ma position GPS</button></div><div id="area-geostatus" class="hint" style="margin-top:8px">${Number.isFinite(z.lat)?`Centre approximatif : ${Number(z.lat).toFixed(4)}, ${Number(z.lon).toFixed(4)}`:'Définis d’abord le centre de la zone.'}</div></form><p class="hint">Géocodage : © OpenStreetMap (Nominatim). La localisation GPS n'est demandée que lorsque tu appuies sur le bouton.</p>`)}
${card(`<div class="row"><b>Magasins surveillés</b><span class="chip">${STORES.length} sélectionné(s)</span></div><p class="hint">Décoche un magasin pour l'exclure immédiatement du panier, des cotes et des alertes dans cette zone.</p>${z.stores.length?z.stores.map((x,i)=>`<div class="item"><div class="row"><label style="display:flex;align-items:center;gap:9px;flex:1"><input type="checkbox" data-area-toggle="${i}" ${x.selected?'checked':''} style="width:auto;min-width:18px"><span><b>${E(x.name)}</b><span class="hint" style="display:block">${x.osmId?'Magasin lié à OpenStreetMap':'Magasin manuel / à relier à OpenStreetMap'}${!storeInArea(x,z)?' · hors du rayon (exclu)':''}${Number.isFinite(x.lat)&&Number.isFinite(z.lat)?' · '+num(distKm(z.lat,z.lon,x.lat,x.lon),1)+' km':''}</span></span></label><button class="btn danger sm" data-area-delete="${i}" title="Retirer de la zone">✕</button></div>${x.url?`<a class="small" href="${E(x.url)}" target="_blank" rel="noopener noreferrer">Ouvrir le Drive</a>`:''}</div>`).join(''):'<div class="empty">Aucun magasin sélectionné. Lance une recherche de magasins.</div>'}<div class="field" style="margin-top:12px"><form id="area-manual"><label>Ajouter un magasin manuellement</label><input id="area-manual-name" placeholder="Ex. Carrefour Market Hyères" maxlength="100" required><button class="btn secondary sm" style="margin-top:8px">+ Ajouter</button></form></div>`)}
${card(`<b>1. Trouver les supermarchés de la zone</b><p class="hint">Recherche ponctuelle dans OpenStreetMap. Tu sélectionnes ensuite ceux que tu souhaites surveiller. Ne donne pas leurs prix : elle trouve les adresses et leur identifiant.</p><button id="area-find" class="btn secondary wide" ${Number.isFinite(z.lat)?'':'disabled'}>🔎 Chercher les supermarchés proches</button><div id="area-shops" class="area-results">${discoveredShops.length?drawFoundShops():''}</div>`)}
${card(`<b>2. Rechercher les prix relevés dans les magasins</b><p class="hint">Open Prices contient des relevés collaboratifs datés. Les résultats sont liés au magasin OpenStreetMap exact. Il peut ne rien y avoir pour certaines enseignes.</p><button id="area-scan" class="btn wide" ${z.stores.some(x=>x.selected&&x.osmId)?'':'disabled'}>↻ Chercher les prix de mes magasins</button><div id="area-prices" class="area-results">${areaPriceMeta?`<p class="hint">${E(areaPriceMeta)}</p>${drawAreaPrices()}`:''}</div>`)}
${card(`<b>3. Quand les prix sont indisponibles</b><p class="hint">Tu peux ouvrir le Drive, prendre une photo de l’étiquette ou saisir le prix. Les catalogues de Carrefour, Leclerc, Intermarché, Auchan et Courses U ne sont pas récupérés automatiquement par cette V1.3.</p><button id="zone-add-price" class="btn secondary wide">+ Relever un prix dans ce secteur</button>`)}
${card(`<b>Sources & confidentialité</b><p class="hint">© contributeurs OpenStreetMap (ODbL), Nominatim, Overpass ; Open Prices / Open Food Facts (ODbL). Les résultats sont indicatifs et non exhaustifs. Les zones et les prix personnels restent dans ce navigateur, sauf quand tu exportes ta sauvegarde.</p>`)}`}
function drawFoundShops(){const z=activeZone();return discoveredShops.slice(0,100).map((o,i)=>{let known=z.stores.some(s=>s.osmId===o.osmId&&s.osmType===o.osmType);let d=Number.isFinite(o.distance)?`${num(o.distance,1)} km`:'distance inconnue';let possible=z.stores.filter(s=>!s.osmId),options=possible.map(s=>`<option value="${E(s.id)}">Relier à : ${E(s.name)}</option>`).join('');return `<div class="item"><div class="row"><div><b>${E(o.name)}</b><div class="hint">${E(o.city||'')} · ${d}</div></div><button class="btn ${known?'ghost':'secondary'} sm" ${known?'disabled':''} data-area-add="${i}">${known?'Ajouté':'+ Suivre'}</button></div>${!known&&options?`<select style="margin-top:7px" aria-label="Associer ${E(o.name)} à un magasin déjà suivi" id="area-link-${i}"><option value="">Nouveau magasin</option>${options}</select>`:''}</div>`}).join('')}
function normalizeOSM(element,z){let t=element.tags||{},lat=element.lat??element.center?.lat,lon=element.lon??element.center?.lon;if(!Number.isFinite(lat)||!Number.isFinite(lon))return null;const brand=t.brand||t.name||t.operator||'Supermarché';return {name:t.name||brand,city:t['addr:city']||t['addr:postcode']||'',osmId:element.id,osmType:String(element.type||'').toUpperCase(),lat,lon,distance:distKm(z.lat,z.lon,lat,lon)}}
function fetchWithTimeout(url,options={},timeout=18000){return fetch(url,{...options,signal:AbortSignal.timeout(timeout),headers:{Accept:'application/json',...(options.headers||{})}})}
async function lookupCity(){const place=el('area-place').value.trim(),radius=+el('area-radius').value,box=el('area-geostatus');if(place.length<2){toast('Indique une ville ou un code postal.','error');return}box.textContent='Recherche du centre de la ville…';try{const q=new URL('https://nominatim.openstreetmap.org/search');q.searchParams.set('q',place);q.searchParams.set('format','jsonv2');q.searchParams.set('limit','3');q.searchParams.set('addressdetails','1');const r=await fetchWithTimeout(q.toString());if(!r.ok)throw Error('HTTP '+r.status);const places=await r.json();let a=places.find(p=>p.address?.country_code==='fr')||places[0];if(!a)throw Error('Ville introuvable. Essaie « nom + code postal + France ».');let lat=Number(a.lat),lon=Number(a.lon);if(!Number.isFinite(lat)||!Number.isFinite(lon))throw Error('Coordonnées indisponibles');applyLocation(place,lat,lon,radius);toast('Zone mise à jour. Recherche maintenant tes magasins.')}catch(err){box.textContent='Recherche impossible : '+err.message+' · Tu peux essayer « Ma position GPS ».'}}
function applyLocation(place,lat,lon,radius){const z=activeZone(),moved=Number.isFinite(z.lat)&&distKm(z.lat,z.lon,lat,lon)>2;z.place=place;z.lat=lat;z.lon=lon;z.radius=radius;if(moved){z.stores.forEach(s=>{if(s.osmId){s.selected=false}else if(z.id==='holiday'){s.selected=false}});discoveredShops=[];areaPrices=[];areaPriceMeta=''}refreshStores();persist();render()}
async function gpsLocation(){const z=activeZone();if(!navigator.geolocation){toast('Géolocalisation indisponible.','error');return}el('area-geostatus').textContent='Demande de ta position GPS…';navigator.geolocation.getCurrentPosition(p=>{applyLocation('Position GPS',p.coords.latitude,p.coords.longitude,+el('area-radius').value);toast('Zone GPS appliquée.')},err=>{el('area-geostatus').textContent='GPS refusé ou indisponible : '+err.message},{enableHighAccuracy:false,timeout:15000,maximumAge:60000})}
async function discoverStores(){const z=activeZone(),out=el('area-shops');if(!Number.isFinite(z.lat)||!Number.isFinite(z.lon)){toast('Définis une ville ou utilise le GPS.','error');return}out.innerHTML='<p class="hint">Recherche des magasins dans OpenStreetMap…</p>';const rkm=Math.min(50,Math.max(1,z.radius));const q=`[out:json][timeout:20];(nwr["shop"="supermarket"](around:${Math.round(rkm*1000)},${z.lat},${z.lon}););out center;`;
try{const url='https://overpass.kumi.systems/api/interpreter?data='+encodeURIComponent(q);let r;try{r=await fetchWithTimeout(url,{},25000)}catch{r=await fetchWithTimeout('https://overpass-api.de/api/interpreter?data='+encodeURIComponent(q),{},25000)}if(!r.ok)throw Error('Service cartographique temporairement indisponible ('+r.status+')');let result=await r.json();discoveredShops=(result.elements||[]).map(x=>normalizeOSM(x,z)).filter(x=>x&&x.distance<=z.radius).sort((a,b)=>a.distance-b.distance).slice(0,150);out.innerHTML=discoveredShops.length?drawFoundShops():'<div class="empty">Aucun magasin trouvé. Essaie un rayon plus large ou ajoute-le manuellement.</div>';attachShopButtons();}catch(err){out.innerHTML=`<div class="empty">Recherche indisponible (${E(err.message)}). Ajoute un magasin manuellement ou réessaie plus tard.</div>`}}
function attachShopButtons(){document.querySelectorAll('[data-area-add]').forEach(b=>b.onclick=()=>{const i=+b.dataset.areaAdd,x=discoveredShops[i];if(!x)return;const z=activeZone();if(z.stores.some(s=>s.osmId===x.osmId&&s.osmType===x.osmType))return;const rel=el('area-link-'+i)?.value,existing=z.stores.find(s=>s.id===rel&&!s.osmId);if(existing){Object.assign(existing,{osmId:x.osmId,osmType:x.osmType,lat:x.lat,lon:x.lon,distance:x.distance,selected:true});toast('Magasin existant relié à OpenStreetMap.')}else{z.stores.push({...x,id:osmKey(x.osmType,x.osmId),selected:true,url:''});toast('Magasin ajouté : '+x.name)}refreshStores();persist();render()})}
function packFromPrice(p,category){const u=cat(category).unit,per=p.price_per||'UNIT';if(per==='KILOGRAM'&&u==='kg')return {packQty:1,packPrice:N(p.price),perUnit:true};if(per==='LITER'&&u==='L')return {packQty:1,packPrice:N(p.price),perUnit:true};if(per!=='UNIT')return null;let prod=p.product||{},text=String(prod.quantity||''),unit=String(prod.product_quantity_unit||'').toLowerCase(),value=N(prod.product_quantity);let multi=text.match(/(\d{1,2})\s*[x×]\s*([\d.,]+)\s*(kg|g|ml|cl|l)\b/i);let match=text.match(/([\d.,]+)\s*(kg|g|ml|cl|l)\b/i);if(multi){value=N(multi[1])*N(multi[2]);unit=multi[3].toLowerCase()}else if(match){value=N(match[1]);unit=match[2].toLowerCase()}if(u==='u')return {packQty:1,packPrice:N(p.price),perUnit:false};let factor=(unit==='g'||unit==='ml')?.001:unit==='cl'?.01:1;if(!Number.isFinite(value)||value<=0)return null;if(u==='kg'&&!['kg','g'].includes(unit))return null;if(u==='L'&&!['l','cl','ml'].includes(unit))return null;return {packQty:value*factor,packPrice:N(p.price),perUnit:false}}
function categorySuggestion(p){let s=cleanZoneName([p.product?.product_name,p.product_name,p.product?.brands,p.category_tag].filter(Boolean).join(' '));let rules=[['poulet',/filets? de poulet|blanc de poulet/],['steak',/steaks? hache/],['lait',/lait demi ecreme/],['beurre',/beurre/],['oeufs',/\boeufs?\b/],['pates',/\bpates?\b|\bspaghetti\b|\bpenne\b/],['riz',/\briz\b/],['cafe',/\bcafe\b/],['lessive',/\blessive\b/],['sanytol',/sanytol/],['jambon',/jambon/],['papier',/papier toilette/]];return rules.find(([,r])=>r.test(s))?.[0]||''}
function drawAreaPrices(){if(!areaPrices.length)return '<div class="empty">Aucun prix utilisable trouvé. Les relevés manuels restent possibles.</div>';return areaPrices.slice(0,80).map((x,i)=>{const p=x.price;const c=categorySuggestion(p),name=p.product?.product_name||p.product_name||'Produit non identifié';const parsed=c?packFromPrice(p,c):null;return `<div class="item"><b>${E(name)}</b><div class="hint">${E(store(x.storeId))} · ${E(p.date||'date inconnue')} · ${euro(N(p.price))} / ${E(p.price_per||'UNIT')} ${p.price_is_discounted?'· promotion':''}</div><div class="field-grid" style="margin-top:8px"><div class="field"><label>Catégorie à vérifier</label><select id="area-price-cat-${i}"><option value="">Choisir la catégorie</option>${state.categories.map(o=>`<option value="${E(o.id)}" ${o.id===c?'selected':''}>${E(o.name)}</option>`).join('')}</select></div><div class="field"><label>Produit / conditionnement</label><span class="hint">${parsed?`${num(parsed.packQty,3)} ${cat(c).unit}${parsed.perUnit?' (quantité à confirmer : cote seule)':''}`:'Vérifier poids / volume'}</span></div></div><button class="btn secondary sm" data-area-import="${i}">Vérifier et importer</button></div>`}).join('')}
function attachPriceButtons(){document.querySelectorAll('[data-area-import]').forEach(btn=>btn.onclick=()=>{const i=+btn.dataset.areaImport,x=areaPrices[i];if(!x)return;let c=el('area-price-cat-'+i)?.value,p=x.price,name=p.product?.product_name||p.product_name||'Relevé Open Prices';if(!c){toast('Choisis une catégorie.','error');return}const calc=packFromPrice(p,c);if(!calc||!(calc.packQty>0)||!(calc.packPrice>0)){toast('Quantité non déduite. Enregistre ce prix manuellement après vérification.','error');return}if(!p.date||dayAge(p.date)<0){toast('Date de relevé non exploitable.','error');return}if(!confirm(`Confirmer le relevé ${name} chez ${store(x.storeId)} : ${euro(calc.packPrice)} pour ${num(calc.packQty,3)} ${cat(c).unit} ? Vérifie la photo source, le conditionnement et les promotions avant de continuer.`))return;const rec={id:'op-'+String(p.id),category:c,store:x.storeId,name,code:String(p.product_code||p.product?.code||''),packQty:calc.packQty,packPrice:calc.packPrice,date:p.date,source:'Open Prices #'+p.id,packUsable:!calc.perUnit,comment:calc.perUnit?'Prix standardisé au kg/L : conditionnement de vente non vérifié. Non utilisé dans le panier.':'Import vérifié par utilisateur. Source Open Prices (ODbL).'};if(state.prices.some(v=>v.id===rec.id)){toast('Relevé déjà importé.');return}if(savePriceRecord(rec)){toast('Prix importé.');render()}})}
async function scanAreaPrices(){const z=activeZone(),out=el('area-prices'),stores=z.stores.filter(s=>s.selected&&storeInArea(s,z)&&s.osmId&&s.osmType);if(!stores.length){toast('Sélectionne d’abord un magasin géolocalisé.','error');return}out.innerHTML='<p class="hint">Recherche des prix Open Prices par magasin…</p>';areaPrices=[];let errors=0,truncated=0,total=0;const start=new Date(Date.now()-Number(state.settings.maxAge||14)*86400000).toISOString().slice(0,10);
for(const s of stores.slice(0,12)){try{const url=new URL('https://prices.openfoodfacts.org/api/v1/prices');url.searchParams.set('location_osm_id',String(s.osmId));url.searchParams.set('location_osm_type',s.osmType);url.searchParams.set('currency','EUR');url.searchParams.set('date__gte',start);url.searchParams.set('order_by','-date');url.searchParams.set('size','100');const r=await fetchWithTimeout(url.toString(),{},16000);if(!r.ok)throw Error('HTTP '+r.status);const data=await r.json();total+=data.total||0;if((data.pages||1)>1)truncated++;for(const p of Array.isArray(data.items)?data.items:[])if(Number.isFinite(N(p.price))&&N(p.price)>0&&p.date&&dayAge(p.date)>=0&&fresh(p))areaPrices.push({storeId:s.id,price:p})}catch(err){errors++}}
areaPrices.sort((a,b)=>b.price.date.localeCompare(a.price.date));areaPriceMeta=`${areaPrices.length} relevé(s) récupéré(s) pour ${Math.min(stores.length,12)} magasin(s) · ${errors} recherche(s) en échec${truncated?' · résultats partiels pour '+truncated+' magasin(s)':''}. Aucune garantie de couverture intégrale ni de disponibilité en rayon.`;out.innerHTML='<p class="hint">'+E(areaPriceMeta)+'</p>'+drawAreaPrices();attachPriceButtons();if(!areaPrices.length&&errors)toast('Aucun prix importé : le service a refusé ou interrompu certaines requêtes.','error')}
function bindZone(){el('area-home').onclick=()=>enterZone('home');el('area-holiday').onclick=()=>enterZone('holiday');el('area-form').onsubmit=e=>{e.preventDefault();lookupCity()};el('area-gps').onclick=gpsLocation;el('area-find').onclick=discoverStores;el('area-scan').onclick=scanAreaPrices;el('zone-add-price').onclick=()=>go('releve');el('area-radius').onchange=e=>{const n=+e.target.value;activeZone().radius=n;refreshStores();persist();render()};el('area-manual').onsubmit=e=>{e.preventDefault();let name=el('area-manual-name').value.trim();if(!name)return;activeZone().stores.push({id:'manual-'+uid(),name,selected:true,osmId:null,osmType:null,lat:null,lon:null,url:''});persist();render();toast('Magasin ajouté (prix à relever manuellement).')};document.querySelectorAll('[data-area-toggle]').forEach(b=>b.onchange=e=>{activeZone().stores[+b.dataset.areaToggle].selected=e.target.checked;refreshStores();persist();render()});document.querySelectorAll('[data-area-delete]').forEach(b=>b.onclick=()=>{const i=+b.dataset.areaDelete,s=activeZone().stores[i];if(state.prices.some(p=>p.store===s.id)&&!confirm('Retirer ce magasin de la zone ? Ses relevés historiques resteront dans la sauvegarde.'))return;activeZone().stores.splice(i,1);refreshStores();persist();render()});attachShopButtons();attachPriceButtons()}

